    elif cmd=='NAMES':send(s,':irc 366 '+(nick or '*')+' '+(a[1] if len(a)>1 else '*')+' :End of NAMES')
    elif cmd and cmd not in ('PASS','NICK','USER'):send(s,':irc 421 '+(nick or '*')+' '+cmd+' :Unknown command')
 finally:
